  fallbacks: ModelClass[];
}

export interface RoutingSignals {
  inputTokens: number;
  requiresReasoning: boolean;
  requiresCode: boolean;
  hasMultiStepTask: boolean;
  toolCount: number;
  retrievalConfidence?: number;
  tenantTier: "free" | "pro" | "enterprise";
}

export function route(signals: RoutingSignals, budgetCents: number): RoutingDecision {
  const tiers: Record<ModelClass, string> = { fast: FAST_MODEL, standard: DEFAULT_MODEL, deep: DEEP_MODEL };

  let tier: ModelClass = "fast";
  let reason = "default fast path";

  if (signals.requiresReasoning || signals.requiresCode) { tier = "deep"; reason = "reasoning or code required"; }
  else if (signals.hasMultiStepTask || signals.toolCount > 4) { tier = "standard"; reason = "multi-step task"; }
  else if (signals.inputTokens > 8_000) { tier = "standard"; reason = "large context"; }
  else if (signals.retrievalConfidence !== undefined && signals.retrievalConfidence < 0.5) {
    tier = "standard"; reason = "low retrieval confidence; synthesis needed";
  }

  if (signals.tenantTier === "free" && tier === "deep") {
    tier = "standard"; reason += "; downgraded for free tier";
  }
  const est = estimateCost(tiers[tier], signals.inputTokens);
  if (est > budgetCents) {
    return { tier: "fast", reason: reason + "; budget forced fast path", estimatedCostCents: est, fallbacks: [] };
  }
  return {
    tier, reason, estimatedCostCents: est,
    fallbacks: tier === "deep" ? ["standard", "fast"] : tier === "standard" ? ["fast"] : [],
  };
}
```

**3. Cascading / escalation.** Run the small model, and escalate to the large model only when a
verification step fails. This gets the best of both: small-model cost on easy cases, large-model quality
where it matters.

```ts
export async function cascade<T>(
  input: PromptInput,
  verify: (out: T) => Promise<{ ok: boolean; confidence: number; reason: string }>,
  tiers: ModelClass[] = ["fast", "standard", "deep"],
): Promise<{ output: T; tier: ModelClass; attempts: Attempt[]; escalated: boolean }> {
  const attempts: Attempt[] = [];
  let lastOutput: T | null = null;

  for (const tier of tiers) {
    const start = Date.now();
    const res = await generate(input, MODEL_BY_TIER[tier]);
    const parsed = validate(res);                 // schema + business rules
    attempts.push({ tier, latencyMs: Date.now() - start, usage: res.usage,
      stopReason: res.stopReason, valid: parsed.ok });
    if (!parsed.ok) continue;                     // schema failure: escalate, do not repair here
    lastOutput = parsed.value as T;

    const v = await verify(lastOutput);
    if (v.ok && v.confidence >= CONFIDENCE_FLOOR) {
      return { output: lastOutput, tier, attempts, escalated: tier !== tiers[0] };
    }
    // Verification failed or confidence low: escalate.
  }
  // All tiers failed verification. Return the best attempt and flag it, or fall back deterministically.
  return { output: lastOutput as T, tier: tiers[tiers.length - 1], attempts, escalated: true };
}
```

**Escalation triggers that work well:** schema validation failure; deterministic business-rule
violation; low self-reported confidence combined with an explicit contract field; retrieval confidence
below threshold; a verifier model disagreeing; and user-visible failure signals (immediate regeneration,
rapid re-ask).

**Self-consistency as a router.** Run the fast model twice with different seeds; if the structured
outputs agree, accept; if not, escalate. Cheap, uses no extra machinery, and works well for
classification and extraction.

```ts
export async function selfConsistentOrEscalate<T>(input: PromptInput): Promise<{ value: T; agreed: boolean; costCents: number }> {
  const [a, b] = await Promise.all([
    generate(input, FAST_MODEL, { temperature: 0.2, seed: 1 }),
    generate(input, FAST_MODEL, { temperature: 0.8, seed: 2 }),
  ]);
  const va = validate(a), vb = validate(b);
  if (va.ok && vb.ok && stableKeyOrder(va.value) === stableKeyOrder(vb.value)) {
    return { value: va.value as T, agreed: true, costCents: costOf(a.usage).totalCents + costOf(b.usage).totalCents };
  }
  const deep = await generate(input, DEEP_MODEL);
  return { value: validate(deep).value as T, agreed: false, costCents: costOf(deep.usage).totalCents };
}
```

**When to use / when not to.** Use static routing always. Add difficulty routing when you have per-model
quality measurements showing a real gap on your task distribution. Add cascading when verification is
cheap and reliable Ã¢â‚¬â€ cascading is a bet on your verifier, and a bad verifier makes things worse (you pay
for the cheap call *and* the expensive one, and accept a bad answer anyway).

**Trade-offs.** Routing adds a classification step, a second model to maintain, and a class of bugs where
the router sends an easy question to the expensive model (pure waste) or a hard one to the cheap model
(a quality regression users notice). Cascading increases worst-case latency (you pay for two calls) and
worst-case cost. Mitigate by measuring the routing decision's quality directly: what fraction of
"easy" classifications were actually hard, and vice versa.

**Production considerations.**
- Log the routing decision and reason on every request; a router that silently sends everything to the
  deep model is invisible until the bill arrives.
- Maintain a routing confusion matrix in your eval set, same as tool selection.
- Keep per-tier fallback chains and a circuit breaker per tier (13.2.7).
- Model availability differs by tier Ã¢â‚¬â€ the deep model is the one most likely to be rate-limited, so
  your fallback chain matters most exactly when you can least afford a failure.
- Re-evaluate routing whenever you change models; the tiers' relative strengths change.

**Common mistakes.**
- No routing at all, using one model for everything "for consistency."
- A router that is itself an expensive model call.
- Cascading without a good verifier.
- Trusting self-reported confidence alone, which is poorly calibrated in general (better on
  classification than on open generation).
- Forgetting that escalation multiplies cost on exactly the hardest, most expensive-to-serve cases.

**Interviewer probes.**
- "How do you decide which model handles a request?"
- "What is cascading, and when is it worth it?"
- "How do you know your router is right?"

